def second_largest(nums):
    if len(set(nums)) < 2:
        return None

    max_val = float('-inf')
    second_max = float('-inf')

    for x in nums:
        if x > max_val:
            second_max = max_val
            max_val = x
        elif max_val > x > second_max:
            second_max = x

    return second_max
